"""Render four context probes with explicit reference/AI attribution."""
import copy,json,subprocess
from pathlib import Path
import numpy as np,soundfile as sf
import rock_prompt_diagnostic as d
g=d.g;OUT=d.OUT;RATE=44100

def metrics(ep):
    result={}
    for role,s in g.rock.ROLES.items():
        notes=[n for n in ep['notes'] if n[3]==s['id']];active=np.zeros(256,dtype=bool)
        for n in notes:
            left=max(3840,n[1]);right=min(11520,n[1]+n[2])
            if left<right:active[(left-3840)//30:(right-3840)//30]=True
        onsets=sum(3840<=n[1]<11520 for n in notes)
        result[role]=dict(new_continuation_notes=onsets,onsets_per_beat=onsets/16,sounding_fraction=float(active.mean()))
    return result

def page(p):
    boundary=8*60/p['bpm'];cards=[]
    for label,title in [('step32','Step 32 — selected checkpoint'),('step128','Step 128 — final checkpoint')]:
        players=''
        for condition,caption in [('unprompted','Without a reference prompt'),('prompted','With a two-bar reference prompt')]:
            key=label+'_'+condition
            note=f'First {boundary:.2f}s: '+('dataset reference notes. After that: AI-generated new notes.' if condition=='prompted' else 'AI-generated warmup. After that: AI continuation.')
            players+=f'<article data-condition="{condition}"><h3>{caption}</h3><p>{note}</p><audio controls preload="metadata" src="{key}.mp3"></audio><button class="jump">Play continuation from {boundary:.2f}s</button><p class="position"></p><a download href="{key}.mp3">Download MP3</a></article>'
        cards.append(f'<section data-checkpoint="{label}"><h2>{title}</h2>'+players+'<label>Which continuation sounds better? <select><option value="">Choose</option><option value="prompted">With the reference prompt</option><option value="unprompted">Without the reference prompt</option><option>Same</option><option>Neither</option></select></label></section>')
    script='''const boundary=BOUNDARY,key='rock-prompt-diagnostic-v1';let saved=JSON.parse(localStorage.getItem(key)||'{}');for(const s of document.querySelectorAll('section[data-checkpoint]')){const q=s.querySelector('select');q.value=saved[s.dataset.checkpoint]||'';q.onchange=()=>{saved[s.dataset.checkpoint]=q.value;localStorage.setItem(key,JSON.stringify(saved))};for(const card of s.querySelectorAll('article')){const a=card.querySelector('audio');card.querySelector('.jump').onclick=()=>{a.currentTime=boundary;a.play().catch(()=>document.getElementById('status').textContent='Press the audio play button to listen.')};a.ontimeupdate=()=>card.querySelector('.position').textContent=a.currentTime>=boundary?'AI continuation':(card.dataset.condition==='prompted'?'Dataset reference prompt':'AI-generated warmup')}}for(const a of document.querySelectorAll('audio'))a.onplay=()=>{for(const b of document.querySelectorAll('audio'))if(a!==b)b.pause()};document.getElementById('save').onclick=()=>{const rows=[...document.querySelectorAll('section[data-checkpoint]')].map(s=>({checkpoint:s.dataset.checkpoint,choice:s.querySelector('select').value}));if(rows.some(r=>!r.choice)){document.getElementById('status').textContent='Choose one answer for each checkpoint.';return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({schema:key,seed:9976201,rows},null,2)],{type:'application/json'}));a.download='rock-prompt-diagnostic-v1.json';a.click()};'''.replace('BOUNDARY',repr(boundary))
    (OUT/'player_check.js').write_text(script)
    (OUT/'listen.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Does musical context help?</title><style>body{font:18px/1.6 system-ui;max-width:900px;margin:30px auto;padding:20px;background:#14212b;color:#edf5ef}section{background:#233746;padding:24px;border-radius:16px;margin:24px 0}article{border-top:1px solid #647581;padding:14px 0}audio{width:100%}button,select{font:inherit;padding:10px;margin:10px 0}a{color:#a6e7cb}.position{color:#b8e8cb}</style><h1>Does a real musical prompt help?</h1><p>Compare the four-bar AI continuations. Use the buttons to skip the two-bar context. Both conditions use the same seed, tempo, instruments, goal and sampling rules. Only the initial note context changes. Each clip is about 12 seconds including its release tail.</p><p>The prompted condition contains reference MIDI notes at the beginning. No reference note starts or sustains across the marked boundary, although instrument and reverb tails can remain audible briefly.</p>'''+''.join(cards)+'''<p><button id="save">Download choices</button></p><p id="status" role="status"></p><details><summary>Listen to the actual dataset excerpt</summary><p>This entire example is rendered from dataset MIDI, not generated by our model. Its future notes were not supplied to the inference procedure.</p><audio controls preload="metadata" src="dataset_reference.mp3"></audio></details><p>This is a one-prefix diagnostic, with no new training. An improvement here would support further testing; it would not establish that overall music quality is fixed.</p><script>'''+script+'</script></html>',encoding='utf-8')

def main():
    g.rock.configure();p=json.loads((OUT/'protocol.json').read_text());remote=json.loads((OUT/'remote_verification.json').read_text())
    assert remote['protocol_sha256']==g.sha(OUT/'protocol.json') and remote['frozen_backbone_unchanged'] and remote['no_training']
    g.BARS=6;g.BPM=p['bpm'];seconds=24*60/g.BPM+2;raws={};episodes={}
    for key,info in remote['clips'].items():
        path=OUT/(key+'.json');assert g.sha(path)==info['sha256'];ep=json.loads(path.read_text())
        expected=(p['prefix'] if ep['condition']=='prompted' else [])+[r['note'] for r in ep['decisions']]
        assert sorted(ep['notes'])==sorted(expected)
        if ep['condition']=='prompted':assert sorted(n for n in ep['notes'] if n[1]<3840)==sorted(p['prefix'])
        episodes[key]=ep
    reference=json.loads((OUT/'reference_window.json').read_text());episodes['dataset_reference']=dict(notes=reference['notes'])
    for key,ep in episodes.items():
        directory=OUT/key;directory.mkdir(exist_ok=True);midi=g.export(directory,ep);raw=directory/'raw.wav'
        if not raw.exists():g.render(midi,raw)
        audio,sr=sf.read(raw,always_2d=True);assert sr==RATE
        fixed=np.zeros((round(seconds*RATE),2));n=min(len(audio),len(fixed));fixed[:n]=audio[:n];fixed[-RATE:]*=np.linspace(1,0,RATE)[:,None]
        path=directory/'fixed.wav';sf.write(path,fixed,RATE,subtype='FLOAT');raws[key]=path
        print('Rendered',key,flush=True)
    levels={key:g.loudness(path) for key,path in raws.items()};target=min([-22.]+[-2-(peak-lufs) for lufs,peak in levels.values() if np.isfinite(lufs)])
    checks={}
    for key,raw in raws.items():
        gain=target-levels[key][0] if np.isfinite(levels[key][0]) else 0.;wav=OUT/(key+'.wav');mp3=OUT/(key+'.mp3')
        subprocess.run(['ffmpeg','-y','-v','error','-i',str(raw),'-af',f'volume={gain:.9f}dB','-c:a','pcm_s24le',str(wav)],check=True)
        subprocess.run(['ffmpeg','-y','-v','error','-i',str(wav),'-q:a','2',str(mp3)],check=True)
        decoded=OUT/(key+'_decoded.wav');subprocess.run(['ffmpeg','-y','-v','error','-i',str(mp3),str(decoded)],check=True)
        audio,sr=sf.read(decoded);decoded.unlink();assert np.isfinite(audio).all() and np.max(np.abs(audio))<1
        checks[key]=dict(sha256=g.sha(mp3),seconds=len(audio)/sr,lufs=g.loudness(wav)[0],decoded_peak=float(np.max(np.abs(audio))),continuation=metrics(episodes[key]),midi_action_roundtrip=True)
    g.write_json(OUT/'generation.json',dict(status='complete',clips=checks,reference_prefix_seconds=8*60/p['bpm'],new_training=False,frozen_backbone_unchanged=True))
    page(p);print('PROMPT DIAGNOSTIC READY',flush=True)

if __name__=='__main__':main()
